head.script:
let objParent = $p.parent();
let eCount_1 = 0;
let eCount_2 = 0;


// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > E > onkeydown]<br/>컴포넌트 영역에서 키보드의 키를 누를때 발생합니다.",
    "validation" : [
        "컴포넌트 영역에서 키보드의 키를 누를때 발생하여야 합니다.",
        "키를 누르고 있으면 이벤트가 연속적으로 발생하여야 합니다.",
        "문자 입력에 해당하는 키 입력시 onkeydown 이벤트가 발생한 후 onkeypress 이벤트가 발생하여야 합니다.",
        "자식을 가지는 컴포넌트의 경우 자식 컴포넌트에서 onkeydown 이벤트가 발생하면 부모 컴포넌트로 버블링됩니다.",
        "dataType 속성을 지원하는 컴포넌트의 경우 특정 문자의 입력을 제한하는 상태여도 onkeydown 이벤트는 발생합니다.",
    ]
} 



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // comp 생성 호출
    objParent.scwin.comp_init();
}



objParent.scwin.target1_onkeydown = function (e) {
    // 이벤트 3번만 발생하게 처리
    if(eCount_1 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeydown 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   

        if(eCount_1 == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }  
    }
    eCount_1 += 1;
}



objParent.scwin.target1_onkeyup = function (e) {
    eCount_1 = 0;
    eCount_2 = 0;
}



objParent.scwin.target1_onkeypress = function (e) {
    // 이벤트 3번만 발생하게 처리
    if(eCount_2 < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeypress 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);   

        if(eCount_2 == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }  
    }
    eCount_2 += 1;
}
